/**
 * @planks("the TodoMVC app is loaded")
 * @planks("the todo list is empty")
 * @planks("I type {string} into the new-todo input and press Enter")
 * @planks("the todo {string} appears in the list")
 * @planks("the new-todo input is cleared")
 * @planks("the todo list remains empty")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("the todo {string} has the class {string}")
 * @planks("the todo {string} does not have the class {string}")
 * @planks("I click the {string} toggle")
 * @planks("all todos have the class {string}")
 * @planks("I complete all todos individually")
 * @planks("the {string} checkbox is checked")
 * @planks("I click the \"Clear completed\" button")
 * @planks("the todo list contains only {string}")
 * @planks("the \"Clear completed\" button is not visible")
 * @planks("I click the destroy button for {string}")
 * @planks("the main section is hidden")
 * @planks("the footer section is hidden")
 * @planks("the main section is visible")
 * @planks("the footer section is visible")
 * @planks("the todo-count shows {string}")
 * @planks("I double-click the label for {string}")
 * @planks("the todo has the class {string}")
 * @planks("the edit input contains {string}")
 * @planks("I change the edit input to {string} and press Enter")
 * @planks("I change the edit input to {string} and tab away")
 * @planks("I change the edit input to {string} and press Escape")
 * @planks("I clear the edit input and press Enter")
 * @planks("the todo does not have the class {string}")
 * @planks("the URL hash is {string}")
 * @planks("the todo list shows {string} and {string}")
 * @planks("the todo list shows only {string}")
 * @planks("I navigate to the {string} route")
 * @planks("the {string} filter link has the class {string}")
 * @planks("the {string} filter link does not have the class {string}")
 * @planks("I click the {string} filter link")
 * @planks("I am viewing the active filter")
 * @planks("I am viewing the completed filter")
 * @planks("I complete the todo {string}")
 * @planks("the localStorage key {string} contains an item with title {string}")
 * @planks("localStorage has the following todos")
 * @planks("I reload the app")
 * @planks("the localStorage item for {string} has completed set to true")
 * @planks("the localStorage key {string} has no items")
 * @planks("Persist todos to localStorage")
 * @planks("Restore todos from localStorage on load")
 * @planks("Persist completed state to localStorage")
 * @planks("Persist deleted todos — removed from localStorage")
 * @planks("Persist filter state across reload")
 * @planks("Do not persist editing state")
 * @planks("all todos are completed")
 * @planks("the first todo is completed")
 * @planks("I have stored references to the todo list items")
 * @planks("all previously stored todo references are still attached to the DOM")
 */
(function () {
  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';
  var editingId = null;

  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var todoCount = document.querySelector('.todo-count');
  var filters = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      if (data) { todos = JSON.parse(data); }
    } catch (e) { todos = []; }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilter() {
    var hash = location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function filteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function activeCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function completedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  /**
   * @planks-provisional("features/todo-editing.feature:Edit the first of three todos to empty text does not throw in real browser")
   * @planks-provisional("features/todo-dom-stability.feature:Edit first of three todos to empty text preserves DOM refs in real browser")
   * Stale-removal loop (line ~210) calls removeChild which can trigger reentrant render
   * via the capture-phase blur event handler. Underlying cause of NotFoundError in real
   * browser when editing a todo to empty text with 2+ items present.
   */
  function render() {
    var items = todos;
    var f = getFilter();
    // Build map of existing li elements by data-id
    var existing = {};
    var child = todoList.firstElementChild;
    while (child) {
      var id = Number(child.getAttribute('data-id'));
      existing[id] = child;
      child = child.nextElementSibling;
    }
    var idsSeen = {};
    var fragment = document.createDocumentFragment();
    for (var i = 0; i < items.length; i++) {
      var t = items[i];
      idsSeen[t.id] = true;
      var li;
      if (existing[t.id]) {
        // Reuse existing li element to preserve DOM references
        li = existing[t.id];
        delete existing[t.id];
        // Update class, style, and inner content
        var liClass = '';
        if (t.completed) {
          if (liClass) liClass += ' ';
          liClass += 'completed';
        }
        if (t.id === editingId) {
          if (liClass) liClass += ' ';
          liClass += 'editing';
        }
        li.className = liClass;
        var hidden = (f === 'active' && t.completed) || (f === 'completed' && !t.completed);
        if (hidden) {
          li.setAttribute('style', 'display:none');
        } else {
          li.removeAttribute('style');
        }
        // Update inner content
        var viewDiv = li.querySelector('.view');
        if (!viewDiv) {
          viewDiv = document.createElement('div');
          viewDiv.className = 'view';
          li.appendChild(viewDiv);
        }
        var toggle = viewDiv.querySelector('.toggle');
        if (!toggle) {
          toggle = document.createElement('input');
          toggle.className = 'toggle';
          toggle.type = 'checkbox';
          viewDiv.insertBefore(toggle, viewDiv.firstChild);
        }
        toggle.checked = t.completed;
        var label = viewDiv.querySelector('label');
        if (!label) {
          label = document.createElement('label');
          viewDiv.appendChild(label);
        }
        label.textContent = t.title;
        var destroy = viewDiv.querySelector('.destroy');
        if (!destroy) {
          destroy = document.createElement('button');
          destroy.className = 'destroy';
          viewDiv.appendChild(destroy);
        }
        var editInput = li.querySelector('.edit');
        if (!editInput) {
          editInput = document.createElement('input');
          editInput.className = 'edit';
          li.appendChild(editInput);
        }
        editInput.value = t.title;
      } else {
        // Create new li element
        var liClass = '';
        var hidden = false;
        if (t.completed) {
          if (liClass) liClass += ' ';
          liClass += 'completed';
        }
        if (t.id === editingId) {
          if (liClass) liClass += ' ';
          liClass += 'editing';
        }
        if (f === 'active' && t.completed) hidden = true;
        if (f === 'completed' && !t.completed) hidden = true;
        var html = '<li class="' + liClass + '" data-id="' + t.id + '"' + (hidden ? ' style="display:none"' : '') + '>';
        html += '<div class="view">';
        html += '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>';
        html += '<label>' + escapeHtml(t.title) + '</label>';
        html += '<button class="destroy"></button>';
        html += '</div>';
        html += '<input class="edit" value="' + escapeHtml(t.title) + '">';
        html += '</li>';
        var temp = document.createElement('div');
        temp.innerHTML = html;
        li = temp.firstElementChild;
      }
      fragment.appendChild(li);
    }
    // Remove stale li elements that no longer have a matching todo
    for (var staleId in existing) {
      var stale = existing[staleId];
      if (stale.parentNode) stale.parentNode.removeChild(stale);
    }
    // Replace children in one operation
    todoList.innerHTML = '';
    todoList.appendChild(fragment);

    var count = activeCount();
    var word = count === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';

    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }

    toggleAll.checked = todos.length > 0 && completedCount() === todos.length;

    if (completedCount() === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    var currentFilter = getFilter();
    for (var j = 0; j < filters.length; j++) {
      var a = filters[j];
      var href = a.getAttribute('href');
      if ((href === '#/' && currentFilter === 'all') ||
          (href === '#/active' && currentFilter === 'active') ||
          (href === '#/completed' && currentFilter === 'completed')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    var id = Date.now() + Math.random();
    todos.push({ id: id, title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.length > 0 && completedCount() === todos.length;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allCompleted;
    }
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  /**
   * @planks-provisional("features/todo-editing.feature:Edit the first of three todos to empty text does not throw in real browser")
   * Empty-trimmed-title path calls removeTodo which calls render(). When called from
   * the blur handler during render()'s stale-removal loop, this causes reentrant render
   * and a stale removeChild.
   */
  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    editingId = null;
    render();
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  // --- Event delegation ---

  toggleAll.addEventListener('click', function () {
    toggleAllTodos();
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    editingId = id;
    render();
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.setSelectionRange(editInput.value.length, editInput.value.length);
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var li = e.target.closest('li.editing');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    var editInput = li.querySelector('.edit');
    if (e.keyCode === ENTER_KEY) {
      updateTodo(id, editInput.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      cancelEdit();
    }
  });

  /**
   * @planks-provisional("features/todo-editing.feature:Edit the first of three todos to empty text does not throw in real browser")
   * @planks-provisional("features/todo-dom-stability.feature:Edit first of three todos to empty text preserves DOM refs in real browser")
   * Capture-phase blur listener. When the editing LI is removed from the DOM during
   * render()'s stale-removal loop, the blur event fires synchronously and calls
   * updateTodo(), which re-enters render() — the root cause of the NotFoundError crash.
   */
  todoList.addEventListener('blur', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li.editing');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    updateTodo(id, editInput.value);
  }, true);

  window.addEventListener('hashchange', function () {
    editingId = null;
    loadTodos();
    render();
  });

  // --- Init ---
  loadTodos();
  render();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const { JSDOM } = require('happy-dom');

// ---------------------------------------------------------------------------
// Background
// ---------------------------------------------------------------------------

Given('the TodoMVC app is loaded', function () {
  // Already loaded by Before hook in world.js.
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getTodos(doc) {
  return Array.from(doc.querySelectorAll('.todo-list li')).filter(function (li) {
    var style = li.getAttribute('style') || '';
    return style.indexOf('display:none') === -1;
  });
}

function findTodo(doc, title) {
  const items = getTodos(doc);
  return items.find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
}

function assertTodoExists(doc, title) {
  const todo = findTodo(doc, title);
  if (!todo) throw new Error(`Expected todo "${title}" to exist in the list`);
  return todo;
}

function assertTodoNotExists(doc, title) {
  const todo = findTodo(doc, title);
  if (todo) throw new Error(`Expected todo "${title}" to NOT exist in the list`);
}

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given(/^the todo list is empty$/, function () {
  const items = getTodos(this.document);
  assert.strictEqual(items.length, 0, 'Expected empty todo list');
});

Given(/^the todo list has the item "([^"]+)"$/, function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given(/^the todo list has the items "([^"]+)" and "([^"]+)"$/, function (title1, title2) {
  const input = this.document.querySelector('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.value = title2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('all todos are completed', function () {
  var toggles;
  while ((toggles = this.document.querySelectorAll('.toggle:not(:checked)')).length > 0) {
    toggles[0].dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }
});

Given('the first todo is completed', function () {
  var toggles = this.document.querySelectorAll('.toggle:not(:checked)');
  if (toggles.length > 0) {
    toggles[0].dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }
});

Given('I have stored references to the todo list items', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  this._storedRefs = Array.from(items);
  // Record the data-id for each stored ref, to handle items removed by clear/delete
  this._storedRefIds = this._storedRefs.map(function (el) {
    return Number(el.getAttribute('data-id'));
  });
});

Then('all previously stored todo references are still attached to the DOM', function () {
  var refs = this._storedRefs;
  var ids = this._storedRefIds;
  if (!refs || refs.length === 0) {
    throw new Error('No stored references to check');
  }
  // Build set of currently rendered data-ids
  var currentIds = {};
  var currentItems = this.document.querySelectorAll('.todo-list li');
  Array.from(currentItems).forEach(function (li) {
    currentIds[Number(li.getAttribute('data-id'))] = true;
  });
  refs.forEach(function (el, i) {
    var id = ids[i];
    // If the item no longer exists in the rendered list (cleared/deleted), skip
    if (!currentIds[id]) return;
    if (!el || !el.parentNode) {
      throw new Error('Stored reference ' + i + ' (id=' + id + ') is not attached to the DOM');
    }
    // Verify the element is still connected to the document
    var node = el;
    while (node.parentNode) {
      if (node.parentNode === this.document) return;
      node = node.parentNode;
    }
    throw new Error('Stored reference ' + i + ' (id=' + id + ') is not connected to the document');
  }.bind(this));
});

Given(/^the todo list has the completed item "([^"]+)"$/, function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  // Re-query after render
  var toggles = this.document.querySelectorAll('.toggle:not(:checked)');
  if (toggles.length > 0) {
    toggles[0].dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }
});

Given(/^the todo list has the completed item "([^"]+)" and the active item "([^"]+)"$/, function (completedTitle, activeTitle) {
  const input = this.document.querySelector('.new-todo');
  input.value = completedTitle;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  var toggles = this.document.querySelectorAll('.toggle:not(:checked)');
  if (toggles.length > 0) {
    toggles[0].dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }
  input.value = activeTitle;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('the todo list has only active items', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = 'Buy groceries';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.value = 'Walk the dog';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given(/^the URL hash is "([^"]+)"$/, function (hash) {
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Given('localStorage has the following todos:', function (table) {
  const todos = table.hashes().map(row => ({
    id: row.id,
    title: row.title,
    completed: row.completed === 'true',
  }));
  this.localStorage.setItem('todos-javascript', JSON.stringify(todos));
});

Given(/^I am viewing the active filter$/, function () {
  this.navigate('#/active');
});

Given(/^I am viewing the completed filter$/, function () {
  this.navigate('#/completed');
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When(/^I type "([^"]*)" into the new-todo input and press Enter$/, function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I click the toggle checkbox for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const toggle = todo.querySelector('.toggle');
  if (!toggle) throw new Error(`No toggle checkbox found for "${title}"`);
  toggle.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
});

When(/^I click the "([^"]+)" toggle$/, function (label) {
  const toggleAll = this.document.getElementById('toggle-all');
  if (!toggleAll) throw new Error('No toggle-all checkbox found');
  toggleAll.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
});

When('I complete all todos individually', function () {
  var toggles;
  while ((toggles = this.document.querySelectorAll('.toggle:not(:checked)')).length > 0) {
    toggles[0].dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }
});

When(/^I click the "Clear completed" button$/, function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button found');
  btn.click();
});

When(/^I click the destroy button for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const btn = todo.querySelector('.destroy');
  if (!btn) throw new Error(`No destroy button for "${title}"`);
  btn.click();
});

When(/^I double-click the label for "([^"]+)"$/, function (title) {
  const todo = assertTodoExists(this.document, title);
  const label = todo.querySelector('label');
  if (!label) throw new Error(`No label for "${title}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and press Enter$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and tab away$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When(/^I change the edit input to "([^"]*)" and press Escape$/, function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (!editing) throw new Error('No todo in editing mode');
  const editInput = editing.querySelector('.edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When(/^I navigate to the "([^"]+)" route$/, function (hash) {
  this.navigate(hash);
});

When(/^I click the "([^"]+)" filter link$/, function (name) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === name);
  if (!link) throw new Error(`No filter link "${name}" found`);
  link.click();
});

When('I reload the app', function () {
  // Dispose and reload — simulate page reload by creating a fresh window/app.
  // We keep current localStorage (which persists across page reloads in a real browser).
  const stored = {};
  for (let i = 0; i < this.localStorage.length; i++) {
    const key = this.localStorage.key(i);
    stored[key] = this.localStorage.getItem(key);
  }
  const currentHash = this.window.location.hash;
  // Dispose (sets this.window to undefined)
  this.disposeApp();
  // Load the app — create a fresh window
  this.loadApp();
  // Restore hash and localStorage after the fresh window is created
